using System.Collections.ObjectModel; using System.ComponentModel; using System.Runtime.CompilerServices; using System.Windows.Input; using DataMaker.Refactored.Models; using DataMaker.Refactored.Services;
namespace DataMaker.Refactored.ViewModels;
public sealed class LogEntry{public DateTime Time{get;}=DateTime.Now;public string Text{get;init;}="";public string Level{get;init;}="Info";public override string ToString()=> $"[{Time:HH:mm:ss}] {Text}";}
public sealed class MainViewModel:INotifyPropertyChanged
{ public ProjectConfig Config{get;private set;}=new(); public ObservableCollection<LogEntry> Messages{get;}=new(); public ObservableCollection<TestPointResult> TestPoints{get;}=new(); public ObservableCollection<FieldConfig> Fields=>Config.Fields; public CancellationTokenSource? Cancellation{get;private set;} public ICommand GenerateCommand{get;} public ICommand CancelCommand{get;} public event PropertyChangedEventHandler? PropertyChanged; public MainViewModel(){GenerateCommand=new AsyncCommand(GenerateAsync);CancelCommand=new RelayCommand(()=>Cancellation?.Cancel());} public void ReplaceConfig(ProjectConfig value){Config=value;Changed(nameof(Config));Changed(nameof(Fields));} async Task GenerateAsync(){if(Cancellation is not null)return;Messages.Clear();TestPoints.Clear();Cancellation=new();Messages.Add(new LogEntry{Text="开始生成"});var result=await new PipelineService().ExecuteAsync(Config,new Progress<(int,string)>(x=>Messages.Add(new LogEntry{Text=$"测试点 {x.Item1}: {x.Item2}"})),Cancellation.Token);foreach(var point in result.TestPoints)TestPoints.Add(point);foreach(var m in result.Messages)Messages.Add(new LogEntry{Text=m,Level=result.Success?"Info":"Error"});if(result.Success)Messages.Add(new LogEntry{Text=$"完成：{result.ZipPath}"});Cancellation.Dispose();Cancellation=null;} void Changed([CallerMemberName]string? n=null)=>PropertyChanged?.Invoke(this,new(n));}
public sealed class RelayCommand(Action execute):ICommand{public event EventHandler? CanExecuteChanged { add { } remove { } } public bool CanExecute(object? p)=>true;public void Execute(object? p)=>execute();}
public sealed class AsyncCommand(Func<Task> execute):ICommand{public event EventHandler? CanExecuteChanged { add { } remove { } } public bool CanExecute(object? p)=>true;public async void Execute(object? p)=>await execute();}
